create table public.courses (id uuid primary key default gen_random_uuid(), slug text unique not null, title text not null, description text, weeks integer, stripe_price_id text unique, cover_focus_x smallint not null default 50 check (cover_focus_x between 0 and 100), cover_focus_y smallint not null default 50 check (cover_focus_y between 0 and 100), cover_card_focus_x smallint not null default 50 check (cover_card_focus_x between 0 and 100), cover_card_focus_y smallint not null default 50 check (cover_card_focus_y between 0 and 100), cover_sales_focus_x smallint not null default 50 check (cover_sales_focus_x between 0 and 100), cover_sales_focus_y smallint not null default 50 check (cover_sales_focus_y between 0 and 100), cover_cabinet_focus_x smallint not null default 50 check (cover_cabinet_focus_x between 0 and 100), cover_cabinet_focus_y smallint not null default 50 check (cover_cabinet_focus_y between 0 and 100), grants_calorie_calculator boolean not null default false, published boolean not null default false);
create table public.enrollments (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, course_id uuid not null references public.courses(id) on delete cascade, stripe_checkout_session_id text unique not null, created_at timestamptz not null default now(), unique(user_id, course_id));
create table public.lessons (id uuid primary key default gen_random_uuid(), course_id uuid not null references public.courses(id) on delete cascade, title text not null, content text, video_url text, position integer not null default 0, published boolean not null default false);
alter table public.courses enable row level security; alter table public.enrollments enable row level security; alter table public.lessons enable row level security;
create policy "Published courses are readable" on public.courses for select using (published = true);
create policy "Users read own enrollments" on public.enrollments for select using (auth.uid() = user_id);
create policy "Users read lessons for enrolled courses" on public.lessons for select using (published = true and exists (select 1 from public.enrollments where enrollments.course_id = lessons.course_id and enrollments.user_id = auth.uid()));
alter table public.courses add column if not exists price numeric;
alter table public.courses add column if not exists old_price numeric;
insert into public.courses (slug,title,description,weeks,published) values ('deep-core','Deep Core','A focused 6-week core program.',6,false) on conflict (slug) do update set title = excluded.title, description = excluded.description, weeks = excluded.weeks;
